import{_ as e,o as t,c as i,a}from"./app.83c7065c.js";const u=JSON.parse('{"title":"RN Animated API使用","description":"","frontmatter":{"title":"RN Animated API使用","date":"2018-03-29"},"headers":[],"relativePath":"2018/rn-animated-api-usage.md","lastUpdated":1786184870000}'),o={name:"2018/rn-animated-api-usage.md"},d=a('<p>RN 也用了小一段时间了，之前都着重实现功能+赶工期，交互体验方面基本无暇顾及。<br> 最近项目周期不算太紧，于是小小试验了一下 Animated 的 API，模拟器上的效果还不错。 简单记录一下 API 的内容，以后备查： ---先挖坑，以后再填---</p><ol><li>组件</li></ol><ul><li>自带的有<code>Animated.View</code>, <code>Animated.Image</code>, <code>Animated.Text</code><br> 一般用上面的基本就足够了，或者基于上面 3 个自行封装新的动画组件</li><li>还可以用<code>createAnimatedComponent()</code>方法创建自定义的动画组件<br> 用过方法包装自己封装的扩展<code>button</code>组件，动画效果没出来，不知道是不是因为自己的<code>button</code>用了其他非<code>Animated</code>组件的原因</li></ul><ol start="2"><li>API</li></ol><ul><li>timing</li><li>spring</li><li>interpolate</li></ul><ol start="3"><li>单个动画实现</li><li>组合动画实现</li></ol>',6),l=[d];function n(c,r,s,_,m,p){return t(),i("div",null,l)}const I=e(o,[["render",n]]);export{u as __pageData,I as default};
